/* Privileged exec                                                           */
/* ------------------------------------------------------------------------- */

/**
 * @brief DISABLE: back to user exec.
 * @param ctx Unused.
 * @return 0.
 */
int cli_disable(const MenuCommandContext *ctx)
{
    (void)ctx;
    Menu_SetMode(MENU_MODE_EXEC);
    return 0;
}

/**
 * @brief Parse and check a word-aligned address argument.
 * @param s    Address text.
 * @param addr Parsed address.
 * @return 0 on success, -1 (message printed) on a bad or unaligned address.
 */
static int cli_parse_addr(const char *s, uint32_t *addr)
{
    if (cli_parse_u32(s, addr) != 0) {
        return cli_bad_value("address", s);
    }
    if ((*addr & 3u) != 0u) {
        fmt_printf("%% Address 0x%08X is not word aligned\n", (unsigned)*addr);
        return -1;
    }
    return 0;
}

/**
 * @brief DEBUG READ [ADDR]: raw 32-bit read.
 * @param ctx argv[0] = address.
 * @return 0, or -1 for a bad address.
 */
int cli_debug_read(const MenuCommandContext *ctx)
{
    uint32_t addr;
    if (cli_parse_addr(ctx->argv[0], &addr) != 0) {
        return -1;
    }
    fmt_printf("0x%08X = 0x%08X\n", (unsigned)addr, (unsigned)board_debug_read32((uintptr_t)addr));
    return 0;
}

/**
 * @brief DEBUG WRITE [ADDR] [VALUE]: raw 32-bit write, then read back.
 * @param ctx argv[0] = address, argv[1] = value.
 * @return 0, or -1 for a bad address or value.
 */
int cli_debug_write(const MenuCommandContext *ctx)
{
    uint32_t addr;
    uint32_t value;
    if (cli_parse_addr(ctx->argv[0], &addr) != 0) {
        return -1;
    }
    if (cli_parse_u32(ctx->argv[1], &value) != 0) {
        return cli_bad_value("value", ctx->argv[1]);
    }
    board_debug_write32((uintptr_t)addr, value);
    fmt_printf("0x%08X <- 0x%08X (reads back 0x%08X)\n", (unsigned)addr, (unsigned)value,
               (unsigned)board_debug_read32((uintptr_t)addr));
    return 0;
}

/**
 * @brief Parse a PHY register number 0..31.
 * @param s   Text.
 * @param reg Parsed register.
 * @return 0, or -1 (message printed).
 */
static int cli_parse_phy_reg(const char *s, uint8_t *reg)
{
    uint32_t v;
    if (cli_parse_u32(s, &v) != 0 || v > CLI_PHY_REG_MAX) {
        return cli_bad_value("PHY register (0..31)", s);
    }
    *reg = (uint8_t)v;
    return 0;
}

/**
 * @brief PHY READ [REG]: one Clause 22 read.
 * @param ctx argv[0] = register.
 * @return 0, or -1 on a bad register or an MDIO error.
 */
int cli_phy_read(const MenuCommandContext *ctx)
{
    const rtlnet_mdio_t *m = cli_phy_bus();
    uint8_t reg;
    uint16_t v = 0u;
    int rc;
    if (m == NULL || cli_parse_phy_reg(ctx->argv[0], &reg) != 0) {
        return -1;
    }
    rc = rtlnet_mdio_read(m, reg, &v);
    if (rc != RTLNET_MDIO_OK) {
        return cli_rc("MDIO read", rc);
    }
    fmt_printf("PHY %u reg %u = 0x%04X\n", (unsigned)m->phy_addr, (unsigned)reg, (unsigned)v);
    return 0;
}

/**
 * @brief PHY WRITE [REG] [VALUE]: one Clause 22 write, then read back.
 * @param ctx argv[0] = register, argv[1] = 16-bit value.
 * @return 0, or -1 on a bad argument or an MDIO error.
 */
int cli_phy_write(const MenuCommandContext *ctx)
{
    const rtlnet_mdio_t *m = cli_phy_bus();
    uint8_t reg;
    uint32_t v;
    uint16_t rb = 0u;
    if (m == NULL || cli_parse_phy_reg(ctx->argv[0], &reg) != 0) {
        return -1;
    }
    if (cli_parse_u32(ctx->argv[1], &v) != 0 || v > 0xFFFFu) {
        return cli_bad_value("16-bit value", ctx->argv[1]);
    }
    if (cli_rc("MDIO write", rtlnet_mdio_write(m, reg, (uint16_t)v)) != 0) {
        return -1;
    }
    (void)rtlnet_mdio_read(m, reg, &rb);
    fmt_printf("PHY %u reg %u <- 0x%04X (reads back 0x%04X)\n", (unsigned)m->phy_addr, (unsigned)reg, (unsigned)v,
               (unsigned)rb);
    return 0;
}

/**
 * @brief PHY DUMP: registers 0..31 of the current page.
 * @param ctx Unused.
 * @return 0, or -1 on an MDIO error.
 */
int cli_phy_dump(const MenuCommandContext *ctx)
{
    const rtlnet_mdio_t *m = cli_phy_bus();
    uint16_t regs[RTLNET_PHY_NUM_REGS];
    (void)ctx;
    if (m == NULL) {
        return -1;
    }
    if (cli_rc("PHY dump", rtlnet_phy_rtl8211e_dump(m, regs)) != 0) {
        return -1;
    }
    for (unsigned r = 0; r < RTLNET_PHY_NUM_REGS; r++) {
        fmt_printf("%s%2u: %04X", (r % 8u) == 0u ? "  " : "   ", r, (unsigned)regs[r]);
        if ((r % 8u) == 7u) {
            fmt_printf("\n");
        }
    }
    return 0;
}

/**
 * @brief CLEAR COUNTERS: clear the counters of every present core.
 * @param ctx Unused.
 * @return 0.
 */
int cli_clear_counters(const MenuCommandContext *ctx)
{
    const netmgr_present_t *p = netmgr_present();
    (void)ctx;
    if (p->mac) {
        rtlnet_eth_mac_clear_counters(RTLNET_PLAT_MAC_BASE);
    }
    if (p->prot) {
        rtlnet_eth_protocol_clear_counters(RTLNET_PLAT_PROT_BASE);
    }
    if (p->arp) {
        rtlnet_arp_clear_counters(RTLNET_PLAT_ARP_BASE);
    }
    if (p->icmp) {
        rtlnet_icmp_clear_counters(RTLNET_PLAT_ICMP_BASE);
    }
    if (p->dhcp) {
        rtlnet_dhcp_clear_counters(RTLNET_PLAT_DHCP_BASE);
    }
    if (p->iperf) {
        rtlnet_iperf_clear_counters(RTLNET_PLAT_IPERF_BASE);
    }
    if (p->udp) {
        rtlnet_udp_socket_clear_counters(RTLNET_PLAT_UDP_BASE);
    }
    if (p->echo) {
        rtlnet_udp_echo_clear_counters(RTLNET_PLAT_ECHO_BASE);
    }
    (void)cpupath_cls_clear_counters();
    if (rtlnet_axi_arbiter_probe(RTLNET_PLAT_ARB_BASE, NULL) == 0) {
        rtlnet_axi_arbiter_clear(RTLNET_PLAT_ARB_BASE);
        rtlnet_axi_arbiter_err_clear(RTLNET_PLAT_ARB_BASE);
    }
    if (rtlnet_vdma_s2mm_probe(RTLNET_PLAT_S2MM_BASE, NULL) == 0) {
        rtlnet_vdma_s2mm_clear(RTLNET_PLAT_S2MM_BASE);
        rtlnet_vdma_s2mm_err_clear(RTLNET_PLAT_S2MM_BASE);
    }
    if (rtlnet_framebuf_probe(RTLNET_PLAT_FB_BASE, NULL) == 0) {
        rtlnet_framebuf_clear(RTLNET_PLAT_FB_BASE);
        venc_clear_counters();
    }
    rtlnet_offload_reset_stats();
    rtlnet_lwip_clear_counters();
    rtlnet_tcp_echo_clear_counters();
    fmt_printf("Counters cleared\n");
    return 0;
}

/**
 * @brief Common part of LED [N] ON / OFF.
 * @param s  LED index text.
 * @param on 1 on, 0 off.
 * @return 0, or -1 for an index outside 2..7.
 */
static int cli_led(const char *s, int on)
{
    uint32_t n;
    if (cli_parse_u32(s, &n) != 0 || n > CLI_LED_LAST) {
        return cli_bad_value("LED index (2..7)", s);
    }
    if (n < CLI_LED_FIRST_USER) {
        fmt_printf("%% LED %u is not firmware-owned (led0 MMCM lock, led1 heartbeat); use 2..7\n", (unsigned)n);
        return -1;
    }
    plat_led_set((unsigned)n, on);
    fmt_printf("LED %u %s\n", (unsigned)n, on ? "on" : "off");
    return 0;
}

/**
 * @brief LED [N] ON.
 * @param ctx argv[0] = LED index.
 * @return See cli_led.
 */
int cli_led_on(const MenuCommandContext *ctx)
{
    return cli_led(ctx->argv[0], 1);
}

/**
 * @brief LED [N] OFF.
 * @param ctx argv[0] = LED index.
 * @return See cli_led.
 */
int cli_led_off(const MenuCommandContext *ctx)
{
    return cli_led(ctx->argv[0], 0);
}

/**
 * @brief RELOAD: soft restart of the firmware.
 * @param ctx Unused.
 * @return 0 (on the target plat_reload does not return).
 */
int cli_reload(const MenuCommandContext *ctx)
{
    (void)ctx;
    fmt_printf("Reloading...\n");
    plat_reload();
    return 0;
}

