/**
 * @brief Print an on/off word.
 * @param on Nonzero for "on".
 * @return None.
 */
static void cli_print_onoff(int on)
{
    fmt_printf("%s", on ? "on" : "off");
}

/**
 * @brief The lwIP checksum flags as hardware (flag clear) or software (flag set) per protocol.
 * @param f Flags word.
 * @return None.
 */
static void cli_print_cs_flags(uint32_t f)
{
    fmt_printf("0x%04X  GEN ip %s udp %s tcp %s icmp %s | CHECK ip %s udp %s tcp %s icmp %s\n", (unsigned)f,
               (f & RTLNET_CS_GEN_IP) ? "sw" : "hw", (f & RTLNET_CS_GEN_UDP) ? "sw" : "hw",
               (f & RTLNET_CS_GEN_TCP) ? "sw" : "hw", (f & RTLNET_CS_GEN_ICMP) ? "sw" : "hw",
               (f & RTLNET_CS_CHECK_IP) ? "sw" : "hw", (f & RTLNET_CS_CHECK_UDP) ? "sw" : "hw",
               (f & RTLNET_CS_CHECK_TCP) ? "sw" : "hw", (f & RTLNET_CS_CHECK_ICMP) ? "sw" : "hw");
}

/**
 * @brief SHOW OFFLOAD: feature discovery, CTRL, the lwIP checksum flags (and
 *        a MISMATCH line when they disagree), counters, receive policy and
 *        the zero-copy build options.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_offload(const MenuCommandContext *ctx)
{
    static const char *const rx_state_name[] = { "off", "arming (no trailer seen yet)", "on", "draining (rx turned off)" };
    const rtlnet_features_t *f;
    const rtlnet_offload_state_t *st;
    rtlnet_txo_counters_t k;
    const rtlnet_netif_stats_t *ns = rtlnet_netif_stats();
    uint32_t ctrl = 0u;
    uint32_t status = 0u;
    uint32_t flags;
    uint32_t expect;
    (void)ctx;
    rtlnet_features_discover();
    f = rtlnet_features();
    st = rtlnet_offload_state();
    fmt_printf("Checksum offload (CPU path)\n");
    fmt_printf("  Discovery       : wrapper %s, CPU path %s, CPU_CAPS 0x%08X", f->wrapper_ok ? "ok" : "NOT FOUND",
               f->cpu_path ? "present" : "absent", (unsigned)f->cpu_caps);
    fmt_printf(" (classifier %s, offload TX %s, RX %s)\n", f->cls_advertised ? "advertised" : "no",
               f->tx_advertised ? "advertised" : "no", f->rx_advertised ? "advertised" : "no");
    fmt_printf("  Confirmed       : classifier %s, offload TX %s, offload RX %s%s\n", f->cls_present ? "yes" : "no",
               f->tx_present ? "yes" : "no", f->rx_present ? "yes" : "no",
               f->errors ? "  % MISMATCH found at boot, see the log" : "");
    if (!f->tx_present && !f->rx_present) {
        fmt_printf("  Offload         : not present in this build (lwIP computes and checks every checksum)\n");
        return 0;
    }
    (void)rtlnet_offload_ctrl_now(&ctrl);
    (void)rtlnet_offload_status(&status);
    fmt_printf("  Core            : CAPS 0x%08X at 0x%08X, TX buffer %u KB, STATUS 0x%08X (tx %s, rx %s)\n",
               (unsigned)f->block_caps, (unsigned)RTLNET_PLAT_TXO_BASE, (unsigned)rtlnet_offload_buffer_kb(), (unsigned)status,
               (status & RTLNET_TXO_STATUS_TX_IDLE) ? "idle" : "busy", (status & RTLNET_TXO_STATUS_RX_IDLE) ? "idle" : "busy");
    fmt_printf("  CTRL            : 0x%08X  tx-ip ", (unsigned)ctrl);
    cli_print_onoff((ctrl & RTLNET_OFFLOAD_TX_IP) != 0u);
    fmt_printf(", tx-l4 ");
    cli_print_onoff((ctrl & RTLNET_OFFLOAD_TX_L4) != 0u);
    fmt_printf(", rx ");
    cli_print_onoff((ctrl & RTLNET_OFFLOAD_RX) != 0u);
    fmt_printf("  (requested 0x%X, supported 0x%X)\n", (unsigned)rtlnet_offload_request(),
               (unsigned)rtlnet_offload_supported());
    fmt_printf("  RX trailers     : %s\n", rx_state_name[(unsigned)st->rx_state]);
    flags = rtlnet_lwip_get_checksum_ctrl();
    fmt_printf("  lwIP flags      : ");
    cli_print_cs_flags(flags);
    expect = rtlnet_offload_flags_for(ctrl, st->rx_state == RTLNET_RX_TRAILER_ON);
    if (flags != expect) {
        fmt_printf("  %% MISMATCH: lwIP flags 0x%04X, the CTRL read-back implies 0x%04X\n", (unsigned)flags,
                   (unsigned)expect);
    }
    if (rtlnet_offload_counters(&k) == RTLNET_TXO_OK) {
        fmt_printf("  TX counters     : frames %u, ip patched %u, l4 patched %u, skipped %u, malformed %u, dropped %u\n",
                   (unsigned)k.tx_frames, (unsigned)k.tx_ip_patched, (unsigned)k.tx_l4_patched, (unsigned)k.tx_skipped,
                   (unsigned)k.tx_malformed, (unsigned)k.tx_dropped);
        fmt_printf("  RX counters     : frames %u, verified %u, ip bad %u, l4 bad %u, unverified %u\n",
                   (unsigned)k.rx_frames, (unsigned)k.rx_verified, (unsigned)k.rx_ip_bad, (unsigned)k.rx_l4_bad,
                   (unsigned)k.rx_unverified);
    }
    fmt_printf("  RX policy       : trailers %u, passed verified %u, passed unverified %u, dropped bad ip %u, bad l4 %u, "
               "no trailer %u, raw %u\n", (unsigned)st->rx_trailer_frames, (unsigned)st->rx_verified,
               (unsigned)st->rx_unverified, (unsigned)st->rx_drop_ip, (unsigned)st->rx_drop_l4,
               (unsigned)st->rx_no_trailer, (unsigned)st->rx_raw);
    fmt_printf("  Build options   : zero-copy RX %s (%u buffers of %u bytes), zero-copy TX %s; frames sent in place %u, "
               "copied %u, rx no buffer %u\n", RTLNET_NETIF_ZERO_COPY_RX ? "on" : "off", (unsigned)RTLNET_NETIF_RX_BUFS,
               (unsigned)RTLNET_NETIF_BUF_BYTES, RTLNET_NETIF_ZERO_COPY_TX ? "on" : "off", (unsigned)ns->tx_zero_copy,
               (unsigned)ns->tx_copied, (unsigned)ns->rx_no_buf);
    return 0;
}

/**
 * @brief OFFLOAD [WHAT] [STATE] (config): request an offload on or off. WHAT
 *        is tx-ip, tx-l4, rx or all; the request is masked by what the
 *        bitstream has and applied through rtlnet_offload_apply (CTRL first
 *        or lwIP flags first, in the order that never loses a checksum).
 * @param ctx argv[0] = what, argv[1] = on or off.
 * @return 0, or -1 for a bad word or a failed change.
 */
int cli_offload(const MenuCommandContext *ctx)
{
    uint32_t bits;
    uint32_t want = rtlnet_offload_request();
    int on;
    int rc;
    if (cli_word_is(ctx->argv[0], "tx-ip")) {
        bits = RTLNET_OFFLOAD_TX_IP;
    } else if (cli_word_is(ctx->argv[0], "tx-l4")) {
        bits = RTLNET_OFFLOAD_TX_L4;
    } else if (cli_word_is(ctx->argv[0], "rx")) {
        bits = RTLNET_OFFLOAD_RX;
    } else if (cli_word_is(ctx->argv[0], "all")) {
        bits = RTLNET_OFFLOAD_ALL;
    } else {
        return cli_bad_value("offload (tx-ip, tx-l4, rx, all)", ctx->argv[0]);
    }
    if (cli_word_is(ctx->argv[1], "on")) {
        on = 1;
    } else if (cli_word_is(ctx->argv[1], "off")) {
        on = 0;
    } else {
        return cli_bad_value("state (on, off)", ctx->argv[1]);
    }
    rtlnet_features_discover();
    if ((bits & rtlnet_offload_supported()) == 0u) {
        fmt_printf("%% This build has no such offload (see show offload)\n");
        return -1;
    }
    want = on ? (want | bits) : (want & ~bits);
    rc = rtlnet_offload_apply(want);
    if (rc == RTLNET_OFFLOAD_ERR_TIMEOUT) {
        fmt_printf("%% The transmit offload did not go idle: left on, lwIP checksums restored\n");
    } else if (rc == RTLNET_OFFLOAD_ERR_IO) {
        fmt_printf("%% CTRL did not read back as written\n");
    }
    return (rc == RTLNET_OFFLOAD_OK) ? 0 : -1;
}

/* ------------------------------------------------------------------------- */
/* DDR3 memory                                                               */
/* ------------------------------------------------------------------------- */

#define CLI_DDR_DEFAULT_MIB   16u
#define CLI_DDR_MAX_MIB       (RTLNET_PLAT_DDR_SIZE / (1024u * 1024u))
#define CLI_DDR_SEED          0x1D872B41u
#define CLI_DDR_SETTLE_POLLS  20000u   /* bound on the wait for the arbiter's write-in-flight flag */

static const cli_core_t g_core_arb = { "DDR3 arbiter", RTLNET_PLAT_ARB_BASE, RTLNET_ID_ARB };

static unsigned g_ddr_dots;

/**
 * @brief Settle callback of the memory test: order the writes before the reads.
 * @return None. Executes a memory fence, then waits (bounded) for the arbiter to report no write in
 *         flight; a stuck flag ends the wait and the test's compare reports any resulting mismatch.
 */
static void cli_ddr_settle(void)
{
    rtlnet_axi_arbiter_status_t st;
    plat_mem_barrier();
    for (unsigned i = 0; i < CLI_DDR_SETTLE_POLLS; i++) {
        if (rtlnet_axi_arbiter_err_status(RTLNET_PLAT_ARB_BASE, &st) != 0 || !st.wr_busy) {
            return;
        }
    }
}

/**
 * @brief Progress callback of the memory test: one dot per 10 percent.
 * @param percent 0..100 done.
 * @return None.
 */
static void cli_ddr_progress(unsigned percent)
{
    while (g_ddr_dots < percent / 10u) {
        fmt_printf(".");
        g_ddr_dots++;
    }
}

/**
 * @brief Print a rate given in MB/s times 100.
 * @param x100 Rate times 100.
 * @return None.
 */
static void cli_print_rate(uint32_t x100)
{
    fmt_printf("%u.%02u MB/s", (unsigned)(x100 / 100u), (unsigned)(x100 % 100u));
}

/**
 * @brief Print one arbiter master's counters.
 * @param m Master index.
 * @return None.
 */
static void cli_print_arb_master(uint32_t m)
{
    static const char *const names[] = { "CPU caches", "video write DMA", "encoder engine 0", "encoder engine 1" };
    rtlnet_axi_arbiter_counters_t c;
    if (rtlnet_axi_arbiter_read_counters(RTLNET_PLAT_ARB_BASE, m, &c) != 0) {
        return;
    }
    fmt_printf("  Master %u (%s): AW bursts %u, AR bursts %u, W beats %u, R beats %u, errors %u, wait cycles %u\n",
               (unsigned)m, (m < (sizeof(names) / sizeof(names[0]))) ? names[m] : "unused", (unsigned)c.aw_bursts,
               (unsigned)c.ar_bursts, (unsigned)c.w_beats, (unsigned)c.r_beats, (unsigned)c.errors,
               (unsigned)c.wait_cycles);
}

/**
 * @brief Print the arbiter's first-illegal-burst capture: nothing captured, or
 *        the direction, master, address, len, size, burst type and failed rules.
 * @return None.
 */
static void cli_print_arb_capture(void)
{
    static const char *const burst_name[] = { "FIXED", "INCR", "WRAP", "reserved" };
    rtlnet_axi_arbiter_capture_t cap;
    if (rtlnet_axi_arbiter_read_capture(RTLNET_PLAT_ARB_BASE, &cap) != 0) {
        return;
    }
    if (!cap.valid) {
        fmt_printf("  First illegal   : none captured\n");
        return;
    }
    fmt_printf("  First illegal   : %s master %u addr 0x%08X%08X len %u size %u burst %u (%s) failed:%s%s%s\n",
               cap.is_read ? "read (AR)" : "write (AW)", (unsigned)cap.master, (unsigned)cap.addr_hi,
               (unsigned)cap.addr_lo, (unsigned)cap.len, (unsigned)cap.size, (unsigned)cap.burst,
               burst_name[cap.burst & 3u], (cap.fail & RTLNET_ARB_FAIL_BURST) ? " burst-type" : "",
               (cap.fail & RTLNET_ARB_FAIL_SIZE) ? " size" : "", (cap.fail & RTLNET_ARB_FAIL_4K) ? " 4KiB" : "");
}

/**
 * @brief SHOW DDR: DDR3 calibration, the cache setup, the arbiter's identity,
 *        configuration, error status and per-master counters.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_ddr(const MenuCommandContext *ctx)
{
    rtlnet_axi_arbiter_caps_t caps;
    rtlnet_axi_arbiter_status_t st;
    int cal = board_ddr_calibrated();
    (void)ctx;
    fmt_printf("DDR3\n");
    fmt_printf("  Calibration     : %s (init_calib_complete)\n", cal ? "done" : "NOT done");
    fmt_printf("  Memory          : %u MiB at 0x%08X, MT41K256M16 16-bit DDR3-800, AXI4 128-bit on ui_clk\n",
               (unsigned)(RTLNET_PLAT_DDR_SIZE / (1024u * 1024u)), (unsigned)RTLNET_PLAT_DDR_BASE);
    fmt_printf("  Caches          : instruction %u KiB, data %u KiB write-back, %u-byte lines, %u-bit buses, over the window only\n",
               (unsigned)(RTLNET_CPU_ICACHE_BYTES / 1024u), (unsigned)(RTLNET_CPU_DCACHE_BYTES / 1024u),
               (unsigned)RTLNET_PLAT_CACHE_LINE, (unsigned)RTLNET_CPU_CACHE_BUS_BITS);
    if (rtlnet_axi_arbiter_probe(RTLNET_PLAT_ARB_BASE, &caps) != 0) {
        uint32_t id = board_debug_read32(RTLNET_PLAT_ARB_BASE + RTLNET_REG_ID);
        fmt_printf("%% %s not present in this build (ID 0x%08X at 0x%08X, expected 0x%08X)\n", g_core_arb.name,
                   (unsigned)id, (unsigned)g_core_arb.base, (unsigned)g_core_arb.id);
        return 0;
    }
    fmt_printf("  Arbiter         : ID \"ARBT\" 0x%08X, version ", (unsigned)RTLNET_ARB_ID_VALUE);
    cli_print_datecode(RTLNET_ARB_VERSION_VALUE);
    fmt_printf(" at 0x%08X\n", (unsigned)RTLNET_PLAT_ARB_BASE);
    fmt_printf("  Arbiter config  : %u master(s), %u-byte beats, ID width %u, %u outstanding, high-priority mask 0x%02X, narrow mask 0x%02X, wrap mask 0x%02X\n",
               (unsigned)caps.num_masters, (unsigned)caps.bytes_per_beat, (unsigned)caps.id_w,
               (unsigned)caps.max_outstanding, (unsigned)caps.high_prio_mask, (unsigned)caps.narrow_mask,
               (unsigned)caps.wrap_mask);
    if (rtlnet_axi_arbiter_err_status(RTLNET_PLAT_ARB_BASE, &st) == 0) {
        fmt_printf("  Arbiter status  : illegal-burst flag %s, write in flight %u, read in flight %u\n",
                   st.err ? "SET (a burst was answered with SLVERR)" : "clear", (unsigned)st.wr_busy,
                   (unsigned)st.rd_busy);
    }
    for (uint32_t m = 0; m < caps.num_masters; m++) {
        cli_print_arb_master(m);
    }
    cli_print_arb_capture();
    return 0;
}

/**
 * @brief DDR TEST {SIZE}: data-bus, address-bus and random fill/verify test
 *        of SIZE MiB (default 16, 1..512) from 0x80000000, with write and
 *        read rates; the arbiter counters are cleared first and shown after.
 * @param ctx argv[0] = optional size in MiB.
 * @return 0 when the test ran and passed, -1 for a bad size, an uncalibrated
 *         or absent DDR3 path, or a failed test.
 */
int cli_ddr_test(const MenuCommandContext *ctx)
{
    uint32_t mib = CLI_DDR_DEFAULT_MIB;
    ddrtest_result_t r;
    static const char *const phase_name[] = { "none", "data bus", "address bus", "random fill" };
#ifdef RTLNET_FW_IMAGE_DDR
    /* The DDR3 image runs from the first bytes of the tested window: the test would overwrite the running code. */
    fmt_printf("%% ddr test is not available in the DDR3 image (it runs from the tested region)\n");
    return -1;
#endif
    if (ctx->argc > 0 && (cli_parse_u32(ctx->argv[0], &mib) != 0 || mib < 1u || mib > CLI_DDR_MAX_MIB)) {
        return cli_bad_value("size in MiB (1..512)", ctx->argv[0]);
    }
    if (!cli_core_check(&g_core_arb)) {
        return -1;
    }
    if (!board_ddr_calibrated()) {
        fmt_printf("%% DDR3 is not calibrated (see show ddr)\n");
        return -1;
    }
    rtlnet_axi_arbiter_clear(RTLNET_PLAT_ARB_BASE);
    rtlnet_axi_arbiter_err_clear(RTLNET_PLAT_ARB_BASE);
    fmt_printf("DDR3 test: %u MiB at 0x%08X ", (unsigned)mib, (unsigned)RTLNET_PLAT_DDR_BASE);
    g_ddr_dots = 0u;
    if (ddrtest_run(RTLNET_PLAT_DDR_BASE, mib * 1024u * 1024u, CLI_DDR_SEED, cli_ddr_settle, cli_ddr_progress, &r) != 0) {
        fmt_printf("\n%% DDR3 test rejected its arguments\n");
        return -1;
    }
    fmt_printf("\n");
    fmt_printf("  Data bus        : %s (128 walking ones and 128 walking zeros at the first and last line)",
               (r.data_errors == 0u) ? "PASS" : "FAIL");
    if (r.data_errors != 0u) {
        fmt_printf(", %u mismatches", (unsigned)r.data_errors);
    }
    fmt_printf("\n  Address bus     : %s (%u address offsets)", (r.addr_errors == 0u) ? "PASS" : "FAIL",
               (unsigned)r.addr_offsets);
    if (r.addr_errors != 0u) {
        fmt_printf(", %u mismatches", (unsigned)r.addr_errors);
    }
    fmt_printf("\n  Random fill     : %s (%u MiB written and verified)", (r.random_errors == 0u) ? "PASS" : "FAIL",
               (unsigned)mib);
    if (r.random_errors != 0u) {
        fmt_printf(", %u mismatches", (unsigned)r.random_errors);
    }
    fmt_printf("\n  Write           : ");
    cli_print_rate(ddrtest_rate_x100(r.write_bytes, r.write_ticks, RTLNET_PLAT_TICKS_PER_US));
    fmt_printf("  (%u ms)\n  Read            : ", (unsigned)(r.write_ticks / (1000u * RTLNET_PLAT_TICKS_PER_US)));
    cli_print_rate(ddrtest_rate_x100(r.read_bytes, r.read_ticks, RTLNET_PLAT_TICKS_PER_US));
    fmt_printf("  (%u ms)\n", (unsigned)(r.read_ticks / (1000u * RTLNET_PLAT_TICKS_PER_US)));
    if (r.first_phase != DDRTEST_PHASE_NONE) {
        fmt_printf("  First mismatch  : %s at 0x%08X, expected 0x%08X, read 0x%08X\n", phase_name[(unsigned)r.first_phase],
                   (unsigned)r.first_addr, (unsigned)r.first_expected, (unsigned)r.first_actual);
    }
    cli_print_arb_master(0u);
    fmt_printf("DDR3 test %s\n", r.pass ? "PASS" : "FAIL");
    return r.pass ? 0 : -1;
}

