#define CLI_VIDEO_FPS_X100     9000000000ull    /* RTLNET_CSI2_UI_CLK_HZ * 100: fps times 100 from a period */
#define CLI_VIDEO_PCT          100u

static const char *const g_mode_name[RTLNET_CSI2_MODE_COUNT] = { "720p30", "1080p30" };
static const char *const g_source_name[]                     = { "auto", "camera", "pattern" };

#define CLI_PATTERN_SPEED_MAX       32
static const char *const g_pattern_name[] = { "bars", "scroll", "box", "noise", "all" };
#define CLI_PATTERN_SPEED_DEF       4    /* the PATTERN reset speed */

/**
 * @brief Print the test-pattern line from the CSI-2 core's PATTERN and PATTERN_FRAME registers.
 * @param st State read by rtlnet_csi2_rx_read_state.
 * @return None.
 */
static void cli_print_pattern(const rtlnet_csi2_rx_state_t *st)
{
    fmt_printf("  Test pattern    : %s, speed %d px/frame, frame %u since the last restart\n",
               (st->pattern < RTLNET_CSI2_PATTERN_COUNT) ? g_pattern_name[st->pattern] : "unknown", (int)st->pattern_speed,
               (unsigned)st->pattern_frame);
}

/**
 * @brief Print a core identity line: name, ID text, ID value, version and window address.
 * @param core    Core descriptor.
 * @param version VERSION register value.
 * @return None.
 */
static void cli_print_core_line(const cli_core_t *core, uint32_t version)
{
    char txt[5];
    board_id_text(core->id, txt);
    fmt_printf("  %-16s: ID \"%s\" 0x%08X, version ", core->name, txt, (unsigned)core->id);
    cli_print_datecode(version);
    fmt_printf(" at 0x%08X\n", (unsigned)core->base);
}

/**
 * @brief Print the CSI2 STATUS register: the value and the names of the set bits.
 * @param status STATUS value.
 * @return None.
 */
static void cli_print_csi2_status(uint32_t status)
{
    static const struct {
        uint32_t    bit;
        const char *name;
    } flags[] = {
        { RTLNET_CSI2_STATUS_PATTERN,    "pattern-active" },
        { RTLNET_CSI2_STATUS_CLK_RUN,    "camera-clock-running" },
        { RTLNET_CSI2_STATUS_MODE_ERR,   "MODE_ERR" },
        { RTLNET_CSI2_STATUS_PERIOD_ERR, "PERIOD_ERR" },
        { RTLNET_CSI2_STATUS_SOURCE_ERR, "SOURCE_ERR" },
        { RTLNET_CSI2_STATUS_OVERRUN,    "OVERRUN" },
    };
    int first = 1;
    fmt_printf("0x%08X (", (unsigned)status);
    for (unsigned i = 0; i < sizeof(flags) / sizeof(flags[0]); i++) {
        if ((status & flags[i].bit) != 0u) {
            fmt_printf("%s%s", first ? "" : ", ", flags[i].name);
            first = 0;
        }
    }
    fmt_printf("%s)\n", first ? "none" : "");
}

/**
 * @brief SHOW CAMERA: the video source core: mode, source setting, active source, frame period and rate, frame
 *        count, camera timeout and status flags.
 * @param ctx Unused.
 * @return 0 (also when the core is absent: the message says so).
 */
int cli_show_camera(const MenuCommandContext *ctx)
{
    rtlnet_csi2_rx_caps_t caps;
    rtlnet_csi2_rx_state_t st;
    uint32_t fps_x100;
    (void)ctx;
    if (!cli_core_check(&g_core_csi2)) {
        return 0;
    }
    if (rtlnet_csi2_rx_probe(RTLNET_PLAT_CSI2_BASE, &caps) != 0 || rtlnet_csi2_rx_read_state(RTLNET_PLAT_CSI2_BASE, &st) != 0) {
        fmt_printf("%% %s answers with an unexpected VERSION\n", g_core_csi2.name);
        return 0;
    }
    fmt_printf("Camera\n");
    cli_print_core_line(&g_core_csi2, board_debug_read32(RTLNET_PLAT_CSI2_BASE + RTLNET_REG_VERSION));
    fmt_printf("  Capabilities    : %u video modes, test pattern %s, camera front end %s\n", (unsigned)caps.modes,
               caps.pattern ? "yes" : "no", caps.camera ? "yes" : "no");
    if (caps.moving) {
        cli_print_pattern(&st);
    }
    if (st.video_mode < RTLNET_CSI2_MODE_COUNT) {
        fmt_printf("  Video mode      : %s (%ux%u)\n", g_mode_name[st.video_mode],
                   (unsigned)rtlnet_csi2_rx_mode_width(st.video_mode), (unsigned)rtlnet_csi2_rx_mode_height(st.video_mode));
    } else {
        fmt_printf("  Video mode      : unknown (%u)\n", (unsigned)st.video_mode);
    }
    if (st.active_mode < RTLNET_CSI2_MODE_COUNT) {
        fmt_printf("  Active mode     : %s (frame in progress)\n", g_mode_name[st.active_mode]);
    }
    fmt_printf("  Source setting  : %s\n", (st.source <= RTLNET_CSI2_SRC_PATTERN) ? g_source_name[st.source] : "unknown");
    fmt_printf("  Active source   : %s\n", ((st.status & RTLNET_CSI2_STATUS_PATTERN) != 0u) ? "pattern" : "camera");
    fps_x100 = (st.frame_period != 0u) ? (uint32_t)(CLI_VIDEO_FPS_X100 / st.frame_period) : 0u;
    fmt_printf("  Frame period    : %u ui_clk cycles (%u.%02u fps)\n", (unsigned)st.frame_period,
               (unsigned)(fps_x100 / CLI_VIDEO_PCT), (unsigned)(fps_x100 % CLI_VIDEO_PCT));
    fmt_printf("  Frame count     : %u\n", (unsigned)st.frame_count);
    fmt_printf("  Camera timeout  : %u frame periods\n", (unsigned)st.cam_timeout);
    fmt_printf("  Status          : ");
    cli_print_csi2_status(st.status);
    return 0;
}

/**
 * @brief SHOW FRAMEBUFFER: slots, the latest published frame, what the firmware holds, counters, reference counts
 *        and the write DMA.
 * @param ctx Unused.
 * @return 0 (also when a core is absent: the message says so).
 */
int cli_show_framebuffer(const MenuCommandContext *ctx)
{
    rtlnet_framebuf_caps_t caps;
    rtlnet_framebuf_state_t st;
    rtlnet_vdma_s2mm_state_t dma;
    (void)ctx;
    if (!cli_core_check(&g_core_fb) || !cli_core_check(&g_core_s2mm)) {
        return 0;
    }
    if (rtlnet_framebuf_probe(RTLNET_PLAT_FB_BASE, &caps) != 0 || rtlnet_framebuf_read_state(RTLNET_PLAT_FB_BASE, &st) != 0 ||
        rtlnet_vdma_s2mm_probe(RTLNET_PLAT_S2MM_BASE, NULL) != 0 ||
        rtlnet_vdma_s2mm_read_state(RTLNET_PLAT_S2MM_BASE, &dma) != 0) {
        fmt_printf("%% a video core answers with an unexpected VERSION\n");
        return 0;
    }
    fmt_printf("Frame buffer\n");
    cli_print_core_line(&g_core_fb, board_debug_read32(RTLNET_PLAT_FB_BASE + RTLNET_REG_VERSION));
    cli_print_core_line(&g_core_s2mm, board_debug_read32(RTLNET_PLAT_S2MM_BASE + RTLNET_REG_VERSION));
    fmt_printf("  Slots           : %u x %u KiB from DDR3 offset 0x%08X (CPU 0x%08X)\n", (unsigned)caps.slots,
               (unsigned)(caps.slot_bytes / 1024u), (unsigned)st.fb_base, (unsigned)(RTLNET_PLAT_DDR_BASE + st.fb_base));
    if ((st.status & RTLNET_FB_STATUS_LATEST_VALID) != 0u) {
        fmt_printf("  Latest          : slot %u, frame %u, %ux%u, %s, timestamp %u\n",
                   (unsigned)((st.status >> RTLNET_FB_STATUS_LATEST_SHIFT) & RTLNET_FB_STATUS_FIELD_MASK),
                   (unsigned)st.latest.frame, (unsigned)st.latest.width, (unsigned)st.latest.height,
                   st.latest.pattern ? "pattern" : "camera", (unsigned)st.latest.timestamp);
    } else {
        fmt_printf("  Latest          : none published\n");
    }
    if ((st.status & RTLNET_FB_STATUS_FW_HOLDS) != 0u) {
        fmt_printf("  Firmware holds  : slot %u\n",
                   (unsigned)((st.status >> RTLNET_FB_STATUS_FWSLOT_SHIFT) & RTLNET_FB_STATUS_FIELD_MASK));
    } else {
        fmt_printf("  Firmware holds  : none\n");
    }
    fmt_printf("  Published       : %u, dropped %u, bad %u\n", (unsigned)st.published, (unsigned)st.dropped, (unsigned)st.bad);
    fmt_printf("  Reference counts:");
    for (uint32_t i = 0; i < caps.slots && i < RTLNET_FB_MAX_SLOTS; i++) {
        fmt_printf("%s slot %u %u", (i == 0u) ? "" : ",", (unsigned)i, (unsigned)st.refcnt[i]);
    }
    fmt_printf("\n");
    fmt_printf("  Write DMA       : frames ok %u, bad %u, dropped %u, bursts %u, beats %u, status 0x%08X\n",
               (unsigned)dma.frames_ok, (unsigned)dma.frames_bad, (unsigned)dma.frames_dropped, (unsigned)dma.bursts,
               (unsigned)dma.beats, (unsigned)dma.status);
    return 0;
}

/**
 * @brief CAMERA MODE [MODE]: select 720p30 or 1080p30; effective at the next frame start.
 * @param ctx argv[0] = mode name.
 * @return 0, or -1 for a bad name, an absent core or a mode the core rejects.
 */
int cli_camera_mode(const MenuCommandContext *ctx)
{
    uint32_t mode = RTLNET_CSI2_MODE_COUNT;
    int rc;
    for (uint32_t i = 0; i < RTLNET_CSI2_MODE_COUNT; i++) {
        if (cli_word_is(ctx->argv[0], (i == RTLNET_CSI2_MODE_720P30) ? "720p30" : "1080p30")) {
            mode = i;
        }
    }
    if (mode >= RTLNET_CSI2_MODE_COUNT) {
        return cli_bad_value("video mode (720p30 or 1080p30)", ctx->argv[0]);
    }
    if (!cli_core_check(&g_core_csi2)) {
        return -1;
    }
    rc = rtlnet_csi2_rx_set_mode(RTLNET_PLAT_CSI2_BASE, mode);
    if (rc == RTLNET_CSI2_ERR_REJECTED) {
        fmt_printf("%% Video mode %s rejected: the frame period is below its minimum (see camera rate)\n", g_mode_name[mode]);
        return -1;
    }
    if (rc != RTLNET_CSI2_OK) {
        return cli_bad_value("video mode (720p30 or 1080p30)", ctx->argv[0]);
    }
    fmt_printf("Video mode %s (%ux%u), effective at the next frame\n", g_mode_name[mode],
               (unsigned)rtlnet_csi2_rx_mode_width(mode), (unsigned)rtlnet_csi2_rx_mode_height(mode));
    return 0;
}

/**
 * @brief CAMERA SOURCE [SOURCE]: auto, camera or pattern.
 * @param ctx argv[0] = source name.
 * @return 0, or -1 for a bad name, an absent core or a value the core rejects.
 */
int cli_camera_source(const MenuCommandContext *ctx)
{
    uint32_t src = RTLNET_CSI2_SRC_PATTERN + 1u;
    int rc;
    for (uint32_t i = 0; i <= RTLNET_CSI2_SRC_PATTERN; i++) {
        if (cli_word_is(ctx->argv[0], g_source_name[i])) {
            src = i;
        }
    }
    if (src > RTLNET_CSI2_SRC_PATTERN) {
        return cli_bad_value("video source (auto, camera or pattern)", ctx->argv[0]);
    }
    if (!cli_core_check(&g_core_csi2)) {
        return -1;
    }
    rc = rtlnet_csi2_rx_set_source(RTLNET_PLAT_CSI2_BASE, src);
    if (rc != RTLNET_CSI2_OK) {
        fmt_printf("%% Video source %s rejected by the core\n", g_source_name[src]);
        return -1;
    }
    fmt_printf("Video source %s, effective at the next frame\n", g_source_name[src]);
    return 0;
}

/**
 * @brief CAMERA RATE [FPS]: frame rate of the test pattern, 1..30 frames per second.
 * @param ctx argv[0] = frames per second.
 * @return 0, or -1 for a value outside 1..30, an absent core or a period the core rejects.
 */
int cli_camera_rate(const MenuCommandContext *ctx)
{
    uint32_t fps;
    int rc;
    if (cli_parse_u32(ctx->argv[0], &fps) != 0 || fps < 1u || fps > RTLNET_CSI2_FPS_MAX) {
        return cli_bad_value("frame rate in fps (1..30)", ctx->argv[0]);
    }
    if (!cli_core_check(&g_core_csi2)) {
        return -1;
    }
    rc = rtlnet_csi2_rx_set_rate_fps(RTLNET_PLAT_CSI2_BASE, fps);
    if (rc != RTLNET_CSI2_OK) {
        fmt_printf("%% Frame rate %u fps rejected: the period is below the minimum of the video mode\n", (unsigned)fps);
        return -1;
    }
    fmt_printf("Frame rate %u fps (%u ui_clk cycles per frame)\n", (unsigned)fps, (unsigned)(RTLNET_CSI2_UI_CLK_HZ / fps));
    return 0;
}

/**
 * @brief CAMERA PATTERN [PATTERN] {SPEED}: test pattern content (bars, scroll, box, noise, all) and its speed.
 * @param ctx argv[0] = pattern, argv[1] = speed -32..32 (default 4, the reset speed; 0 = still; bars ignore it).
 * @return 0, or -1 for a bad name or speed, an absent core or a value the driver rejects.
 */
int cli_camera_pattern(const MenuCommandContext *ctx)
{
    uint32_t pat = RTLNET_CSI2_PATTERN_ALL + 1u;
    int32_t speed = CLI_PATTERN_SPEED_DEF;
    int rc;
    for (uint32_t i = 0; i <= RTLNET_CSI2_PATTERN_ALL; i++) {
        if (cli_word_is(ctx->argv[0], g_pattern_name[i])) {
            pat = i;
        }
    }
    if (pat > RTLNET_CSI2_PATTERN_ALL) {
        return cli_bad_value("test pattern (bars, scroll, box, noise or all)", ctx->argv[0]);
    }
    if (ctx->argc > 1) {
        const char *t = ctx->argv[1];
        uint32_t mag;
        int neg = (t != NULL && t[0] == '-');
        if (cli_parse_u32(neg ? t + 1 : t, &mag) != 0 || mag > (uint32_t)CLI_PATTERN_SPEED_MAX) {
            return cli_bad_value("pattern speed (-32..32)", ctx->argv[1]);
        }
        speed = neg ? -(int32_t)mag : (int32_t)mag;
    }
    if (!cli_core_check(&g_core_csi2)) {
        return -1;
    }
    rc = rtlnet_csi2_rx_set_pattern(RTLNET_PLAT_CSI2_BASE, pat, speed);
    if (rc != 0) {
        fmt_printf("%% Test pattern %s speed %d rejected by the core\n", g_pattern_name[pat], (int)speed);
        return -1;
    }
    fmt_printf("Test pattern %s, speed %d, effective at the next frame (camera source pattern)\n", g_pattern_name[pat], (int)speed);
    return 0;
}

/**
 * @brief FRAMEBUFFER CRC: CRC-32 of the latest published frame, read through the data cache.
 * @param ctx Unused.
 * @return 0 when the CRC was computed, -1 for an absent core, no published frame or an unusable frame.
 */
int cli_framebuffer_crc(const MenuCommandContext *ctx)
{
    fbcrc_result_t r;
    int rc;
    (void)ctx;
    if (!cli_core_check(&g_core_fb) || !cli_core_check(&g_core_s2mm)) {
        return -1;
    }
    rc = fbcrc_latest(RTLNET_PLAT_FB_BASE, RTLNET_PLAT_S2MM_BASE, RTLNET_PLAT_DDR_BASE, &r);
    if (rc == FBCRC_ERR_NO_FRAME) {
        fmt_printf("%% No frame published yet (or the firmware already holds a slot)\n");
        return -1;
    }
    if (rc != FBCRC_OK) {
        fmt_printf("%% Framebuffer CRC failed (code %d: %s)\n", rc,
                   (rc == FBCRC_ERR_TIMEOUT) ? "take timed out" :
                   (rc == FBCRC_ERR_GEOMETRY) ? "frame geometry does not fit the slot" : "core");
        return -1;
    }
    fmt_printf("Framebuffer CRC-32 : 0x%08X (frame %u, slot %u, %ux%u, %s, %u bytes)\n", (unsigned)r.crc,
               (unsigned)r.frame.frame, (unsigned)r.slot, (unsigned)r.frame.width, (unsigned)r.frame.height,
               r.frame.pattern ? "pattern" : "camera", (unsigned)r.bytes);
    return 0;
}

/* ------------------------------------------------------------------------- */
/* H.264 stream (Phase 2b-3)                                                  */
/* ------------------------------------------------------------------------- */

/**
 * @brief The configured encoder QP.
 * @return QP.
 */
static uint32_t qp_now(void)
{
    venc_status_t s;
    venc_get_status(&s);
    return s.qp;
}

/**
 * @brief STREAM H264 [IP] [PORT]: start the H.264 MPEG-TS stream over UDP.
 * @param ctx argv[0] = host IPv4 address, argv[1] = UDP port.
 * @return 0 when the stream started, -1 for a bad argument, an absent core or a UDP failure.
 */
int cli_stream_h264(const MenuCommandContext *ctx)
{
    uint32_t ip;
    uint32_t port;
    int rc;
    if (cli_parse_ipv4(ctx->argv[0], &ip) != 0) {
        return cli_bad_value("IPv4 address", ctx->argv[0]);
    }
    if (cli_parse_u32(ctx->argv[1], &port) != 0 || port == 0u || port > CLI_UDP_PORT_MAX) {
        return cli_bad_value("UDP port (1..65535)", ctx->argv[1]);
    }
    if (!cli_core_check(&g_core_h264) || !cli_core_check(&g_core_fb)) {
        return -1;
    }
    rc = venc_start(ip, (uint16_t)port);
    if (rc == VENC_ERR_BUSY) {
        fmt_printf("%% A stream is already running (stream stop first)\n");
        return -1;
    }
    if (rc == VENC_ERR_UDP) {
        fmt_printf("%% The UDP socket could not be opened (lwIP not running: link or DHCP not up)\n");
        return -1;
    }
    if (rc != VENC_OK) {
        fmt_printf("%% The encoder or the frame buffer is not usable\n");
        return -1;
    }
    fmt_printf("Streaming H.264 MPEG-TS to %u.%u.%u.%u:%u (VLC: udp://@:%u), QP %u\n", (unsigned)(ip >> 24),
               (unsigned)((ip >> 16) & 0xFFu), (unsigned)((ip >> 8) & 0xFFu), (unsigned)(ip & 0xFFu), (unsigned)port,
               (unsigned)port, (unsigned)qp_now());
    return 0;
}

/**
 * @brief STREAM STOP: stop the H.264 stream.
 * @param ctx Unused.
 * @return 0.
 */
int cli_stream_stop(const MenuCommandContext *ctx)
{
    venc_status_t st;
    (void)ctx;
    venc_get_status(&st);
    if (!st.running) {
        fmt_printf("No stream is running\n");
        return 0;
    }
    venc_stop();
    fmt_printf("Stream stopped after %u pictures\n", (unsigned)st.pictures);
    return 0;
}

/**
 * @brief ENCODER QP [QP]: set the fixed quantizer.
 * @param ctx argv[0] = QP 0..51.
 * @return 0, or -1 for a value outside 0..51.
 */
int cli_encoder_qp(const MenuCommandContext *ctx)
{
    uint32_t qp;
    if (cli_parse_u32(ctx->argv[0], &qp) != 0 || venc_set_qp(qp) != VENC_OK) {
        return cli_bad_value("QP (0..51)", ctx->argv[0]);
    }
    if (qp < RTLNET_H264_CTL_QP_MIN_REALTIME) {
        fmt_printf("QP %u set; the driver writes %u (real-time floor), effective at the next picture\n", (unsigned)qp,
                   (unsigned)RTLNET_H264_CTL_QP_MIN_REALTIME);
    } else {
        fmt_printf("QP %u, effective at the next picture\n", (unsigned)qp);
    }
    return 0;
}

/**
 * @brief ENCODER PROFILE [PROFILE]: select the stream profile, baseline or high.
 * @param ctx argv[0] = profile name.
 * @return 0, or -1 for a bad name, an absent core, or a refused High profile (named reason).
 */
int cli_encoder_profile(const MenuCommandContext *ctx)
{
    int high;
    int rc;
    if (cli_word_is(ctx->argv[0], "baseline")) {
        high = 0;
    } else if (cli_word_is(ctx->argv[0], "high")) {
        high = 1;
    } else {
        return cli_bad_value("profile (baseline or high)", ctx->argv[0]);
    }
    if (!cli_core_check(&g_core_h264)) {
        return -1;
    }
    rc = rtlnet_h264_ctl_set_profile(high);
    if (rc == RTLNET_H264_CTL_HP_ERR_NO_SEAM) {
        fmt_printf("%% Profile high refused: this build has no High profile seam (CAPS HP_SEAM 0)\n");
        return -1;
    }
    if (rc == RTLNET_H264_CTL_HP_ERR_NO_MODULE) {
        fmt_printf("%% Profile high refused: the High profile netlist is not in this build (simulation stub)\n");
        return -1;
    }
    if (rc == RTLNET_H264_CTL_HP_ERR_NO_CAPS) {
        fmt_printf("%% Profile high refused: the High profile module offers no tool yet (hp_caps is 0)\n");
        return -1;
    }
    if (rc == RTLNET_H264_CTL_HP_ERR_NOT_LICENSED) {
        fmt_printf("%% Profile high refused: the High profile license has ended\n");
        return -1;
    }
    if (rc != 0) {
        fmt_printf("%% Profile change failed (code %d)\n", rc);
        return -1;
    }
    if (high) {
        fmt_printf("Profile high, effective at the next picture (an IDR picture with new parameter sets starts it)\n");
    } else {
        fmt_printf("Profile baseline (Constrained Baseline), effective at the next picture\n");
    }
    return 0;
}

/**
 * @brief ENCODER TRANSFORM8X8 [STATE]: the transform of inter macroblocks: auto (the default: the module chooses the 4x4 or the 8x8 transform per
 *        macroblock), on (the 8x8 transform on every inter macroblock) or off (the 4x4 transform).
 * @param ctx argv[0] = on, off or auto.
 * @return 0, or -1 for a bad word, an absent core or a refused request (named reason). Takes effect at the next picture while the profile is high:
 *         between off and on or auto that picture is an IDR picture with new parameter sets.
 */
int cli_encoder_transform8x8(const MenuCommandContext *ctx)
{
    int on;
    int rc;
    if (cli_word_is(ctx->argv[0], "on")) {
        on = RTLNET_H264_CTL_T8_ON;
    } else if (cli_word_is(ctx->argv[0], "off")) {
        on = RTLNET_H264_CTL_T8_OFF;
    } else if (cli_word_is(ctx->argv[0], "auto")) {
        on = RTLNET_H264_CTL_T8_AUTO;
    } else {
        return cli_bad_value("state (on, off or auto)", ctx->argv[0]);
    }
    if (!cli_core_check(&g_core_h264)) {
        return -1;
    }
    rc = rtlnet_venc_set_transform8x8(on);
    if (rc == RTLNET_H264_CTL_HP_ERR_NO_SEAM) {
        fmt_printf("%% Transform8x8 %s refused: this build has no High profile seam (CAPS HP_SEAM 0)\n", (on == RTLNET_H264_CTL_T8_AUTO) ? "auto" : "on");
        return -1;
    }
    if (rc == RTLNET_H264_CTL_HP_ERR_NO_MODULE) {
        fmt_printf("%% Transform8x8 %s refused: the High profile netlist is not in this build (simulation stub)\n", (on == RTLNET_H264_CTL_T8_AUTO) ? "auto" : "on");
        return -1;
    }
    if (rc == RTLNET_H264_CTL_HP_ERR_NO_T8) {
        fmt_printf("%% Transform8x8 %s refused: the High profile module offers no 8x8 transform (hp_caps bit 1 is 0)\n", (on == RTLNET_H264_CTL_T8_AUTO) ? "auto" : "on");
        return -1;
    }
    if (rc == RTLNET_H264_CTL_HP_ERR_NO_AUTO) {
        fmt_printf("%% Transform8x8 auto refused: the High profile module offers no adaptive transform choice (hp_caps bit 2 is 0)\n");
        return -1;
    }
    if (rc != 0) {
        fmt_printf("%% Transform8x8 change failed (code %d)\n", rc);
        return -1;
    }
    if (on == RTLNET_H264_CTL_T8_AUTO) {
        fmt_printf("Transform8x8 auto, effective at the next picture in the High profile (the module chooses the 4x4 or the 8x8 transform per macroblock; an IDR picture with new parameter sets starts it after off)\n");
    } else if (on == RTLNET_H264_CTL_T8_ON) {
        fmt_printf("Transform8x8 on, effective at the next picture in the High profile (an IDR picture with new parameter sets starts it)\n");
    } else {
        fmt_printf("Transform8x8 off (4x4 transform), effective at the next picture\n");
    }
    return 0;
}

/**
 * @brief The Transform 8x8 line of SHOW ENCODER.
 * @return None.
 */
static void cli_print_transform8x8(void)
{
    rtlnet_h264_ctl_hp_t hp;
    if ((rtlnet_h264_ctl_hp_info(&hp) != 0) || (hp.present == 0u)) {
        return;
    }
    if ((hp.caps & RTLNET_H264_CTL_HP_CAP_TRANSFORM8X8) == 0u) {
        fmt_printf("  Transform 8x8   : not offered (hp_caps bit 1 is 0)\n");
        return;
    }
    {
        int         want  = rtlnet_venc_transform8x8_wanted();
        int         force = rtlnet_venc_transform8x8_in_force();
        uint32_t    n8    = 0u;
        uint32_t    n4    = 0u;
        int         adaptive = ((hp.caps & RTLNET_H264_CTL_HP_CAP_ADAPTIVE) != 0u) ? 1 : 0;
        const char *state = (want == RTLNET_H264_CTL_T8_AUTO) ? (adaptive ? "auto" : "on") : ((want != 0) ? "on" : "off");
        const char *use   = (want == RTLNET_H264_CTL_T8_AUTO && adaptive) ? "in force (the module chooses the 4x4 or the 8x8 transform per macroblock)" :
                            "in force (inter macroblocks use the 8x8 transform)";
        fmt_printf("  Transform 8x8   : %s, %s\n", state, force ? use : "not in force (4x4 transform)");
        if (force && (rtlnet_venc_transform8x8_counts(&n8, &n4) == 0)) {
            fmt_printf("  Transform MBs   : last picture 8x8 %u, 4x4 %u\n", (unsigned)n8, (unsigned)n4);
        }
    }
}

/**
 * @brief The High profile line of SHOW ENCODER.
 * @param forced IDR pictures the encoder forced because the license or the profile changed.
 * @return None.
 */
static void cli_print_high_profile(uint32_t forced)
{
    rtlnet_h264_ctl_hp_t hp;
    int rc = rtlnet_h264_ctl_hp_info(&hp);
    if (rc != 0) {
        fmt_printf("  High profile    : not present (this build has no High profile seam)\n");
        return;
    }
    if (hp.present == 0u) {
        fmt_printf("  High profile    : not present (the High profile netlist is not in this build)\n");
        return;
    }
    fmt_printf("  High profile    : present, %s, ", hp.licensed ? "licensed" : "license ended");
    if (hp.seconds_left == RTLNET_H264_CTL_HP_SECONDS_UNLIMITED) {
        fmt_printf("time left unlimited, ");
    } else {
        fmt_printf("time left %u min %u s, ", (unsigned)(hp.seconds_left / 60u), (unsigned)(hp.seconds_left % 60u));
    }
    if (hp.caps == 0u) {
        fmt_printf("tools none (hp_caps 0), ");
    } else {
        fmt_printf("tools%s%s%s (hp_caps %u), ", (hp.caps & RTLNET_H264_CTL_HP_CAP_CABAC) ? " CABAC" : "",
                   (hp.caps & RTLNET_H264_CTL_HP_CAP_TRANSFORM8X8) ? " 8x8-transform" : "",
                   (hp.caps & RTLNET_H264_CTL_HP_CAP_ADAPTIVE) ? " adaptive-choice" : "", (unsigned)hp.caps);
    }
    fmt_printf("profile %s, %u forced IDR pictures\n", hp.enabled ? "high" : "baseline", (unsigned)forced);
}

/**
 * @brief The notification lines of SHOW STREAM and SHOW ENCODER: the mode in force, the interrupt counts per source, the handler time.
 * @param s Session status from venc_get_status.
 * @return None.
 */
static void cli_print_notify(const venc_status_t *s)
{
    const char *want = (s->notify_wanted == VENC_NOTIFY_INTERRUPT) ? "interrupt" : "polled";
    const char *mode = (s->notify_mode == VENC_NOTIFY_INTERRUPT) ? "interrupt" : "polled";
    if (s->notify_mode == s->notify_wanted) {
        fmt_printf("  Notification    : %s%s\n", mode, s->running ? "" : " (requested; applied at the next stream start)");
    } else {
        fmt_printf("  Notification    : %s in force (%s requested: %s)\n", mode, want,
                   s->irq_attached ? "the core has no interrupt registers" : "the interrupt controller is not available");
    }
    if (s->notify_mode == VENC_NOTIFY_INTERRUPT) {
        fmt_printf("  Interrupts      : %u taken (%u with no enabled event); picture done %u, error %u, ring stall %u, profile change %u, license lost %u\n",
                   (unsigned)s->irqs, (unsigned)s->irq_spurious, (unsigned)s->irq_src[RTLNET_H264_CTL_SRC_PIC_DONE],
                   (unsigned)s->irq_src[RTLNET_H264_CTL_SRC_ERR], (unsigned)s->irq_src[RTLNET_H264_CTL_SRC_RING_STALL],
                   (unsigned)s->irq_src[RTLNET_H264_CTL_SRC_PROFILE_CHG], (unsigned)s->irq_src[RTLNET_H264_CTL_SRC_LICENSE_LOST]);
        fmt_printf("  Handler         : %u runs, last %u us, max %u us; pictures started by the handler %u, by the main loop %u, %u starts left to the main loop\n",
                   (unsigned)s->isr_n, (unsigned)s->isr_last_us, (unsigned)s->isr_max_us, (unsigned)s->irq_started,
                   (unsigned)s->main_started, (unsigned)s->irq_parked);
    }
}

/**
 * @brief ENCODER NOTIFY [MODE]: how the end of a picture reaches the firmware, interrupt (default) or polled.
 * @param ctx argv[0] = interrupt or polled.
 * @return 0, or -1 for a bad word. Effective at once when no picture is in flight; a core without the interrupt registers keeps the polled mode.
 */
int cli_encoder_notify(const MenuCommandContext *ctx)
{
    uint32_t mode;
    venc_status_t s;
    if (cli_word_is(ctx->argv[0], "interrupt")) {
        mode = VENC_NOTIFY_INTERRUPT;
    } else if (cli_word_is(ctx->argv[0], "polled")) {
        mode = VENC_NOTIFY_POLLED;
    } else {
        return cli_bad_value("notification mode (interrupt or polled)", ctx->argv[0]);
    }
    (void)venc_set_notify(mode);
    venc_get_status(&s);
    if (mode == VENC_NOTIFY_INTERRUPT) {
        fmt_printf("Notification interrupt requested: the encoder interrupt starts the next picture");
    } else {
        fmt_printf("Notification polled: the main loop reads STATUS and starts the next picture");
    }
    if (!s.running) {
        fmt_printf(" (applied at the next stream start)\n");
    } else if (s.notify_mode != mode) {
        fmt_printf(" (not available: polled stays in force)\n");
    } else {
        fmt_printf("\n");
    }
    return 0;
}

/**
 * @brief ENCODER IRQTEST: force an interrupt event in the core and check that the handler runs.
 * @param ctx Unused.
 * @return 0 when the handler counted the event, -1 otherwise (no stream in interrupt mode, or no interrupt arrived).
 */
int cli_encoder_irqtest(const MenuCommandContext *ctx)
{
    int rc;
    (void)ctx;
    if (!cli_core_check(&g_core_h264)) {
        return -1;
    }
    rc = venc_irq_selftest();
    if (rc == VENC_ERR_ARG) {
        fmt_printf("%% The interrupt test needs a running stream in interrupt mode (stream h264, encoder notify interrupt)\n");
        return -1;
    }
    if (rc != VENC_OK) {
        fmt_printf("%% Interrupt test failed: the forced event raised no interrupt within 20 ms (INTC input or IRQ_ENABLE)\n");
        return -1;
    }
    fmt_printf("Interrupt test passed: a forced ring stall event reached the handler (counted as a ring stall)\n");
    return 0;
}

/**
 * @brief ENCODER GOP [GOP]: set the GOP length (an IDR picture every GOP pictures, P pictures between).
 * @param ctx argv[0] = GOP 1..255.
 * @return 0, or -1 for a value outside 1..255.
 */
int cli_encoder_gop(const MenuCommandContext *ctx)
{
    uint32_t gop;
    if (cli_parse_u32(ctx->argv[0], &gop) != 0 || venc_set_gop(gop) != VENC_OK) {
        return cli_bad_value("GOP (1..255)", ctx->argv[0]);
    }
    if (gop == 1u) {
        fmt_printf("GOP 1 (every picture is an IDR picture), effective at the next picture\n");
    } else {
        fmt_printf("GOP %u (an IDR picture every %u pictures, P pictures between), effective at the next picture\n", (unsigned)gop,
                   (unsigned)gop);
    }
    return 0;
}

/**
 * @brief ENCODER BITRATE [KBPS]: bit rate target of the rate controller.
 * @param ctx argv[0] = kb/s 0..100000 (0 = constant QP).
 * @return 0, or -1 for a value out of range.
 */
int cli_encoder_bitrate(const MenuCommandContext *ctx)
{
    uint32_t kbps;
    if (cli_parse_u32(ctx->argv[0], &kbps) != 0 || venc_set_bitrate(kbps) != VENC_OK) {
        return cli_bad_value("bit rate in kb/s (0..100000, 0 = constant QP)", ctx->argv[0]);
    }
    if (kbps == 0u) {
        fmt_printf("Constant QP %u (rate control off), effective at the next picture\n", (unsigned)qp_now());
    } else {
        fmt_printf("Constant bit rate %u kb/s, effective at the next picture (no IDR picture is forced)\n", (unsigned)kbps);
    }
    return 0;
}

/**
 * @brief ENCODER BUFFER [MS]: size of the rate controller's virtual buffer in milliseconds of the target rate.
 * @param ctx argv[0] = 100..2000.
 * @return 0, or -1 for a value out of range.
 */
int cli_encoder_buffer(const MenuCommandContext *ctx)
{
    uint32_t ms;
    if (cli_parse_u32(ctx->argv[0], &ms) != 0 || venc_set_buffer_ms(ms) != VENC_OK) {
        return cli_bad_value("buffer in ms (100..2000)", ctx->argv[0]);
    }
    fmt_printf("Rate control buffer %u ms of the target rate\n", (unsigned)ms);
    return 0;
}

/**
 * @brief ENCODER QPRANGE [MIN] [MAX]: QP range of the rate controller.
 * @param ctx argv[0] = minimum, argv[1] = maximum (12 <= min <= max <= 51).
 * @return 0, or -1 for a value out of range.
 */
int cli_encoder_qprange(const MenuCommandContext *ctx)
{
    uint32_t lo;
    uint32_t hi;
    if (cli_parse_u32(ctx->argv[0], &lo) != 0 || cli_parse_u32(ctx->argv[1], &hi) != 0 || venc_set_qp_range(lo, hi) != VENC_OK) {
        fmt_printf("%% Invalid QP range \"%s %s\" (12 <= min <= max <= 51)\n", ctx->argv[0], ctx->argv[1]);
        return -1;
    }
    fmt_printf("Rate control QP range %u..%u\n", (unsigned)lo, (unsigned)hi);
    return 0;
}

/**
 * @brief Print a permille figure as "12.3 %".
 * @param pm Value in permille.
 * @return None.
 */
static void cli_print_permille(uint32_t pm)
{
    fmt_printf("%u.%u %%", (unsigned)(pm / 10u), (unsigned)(pm % 10u));
}

/**
 * @brief The rate-control lines shared by SHOW STREAM and SHOW ENCODER: mode and target, measured bit rate, buffer, QP, events, pattern.
 * @return None.
 */
static void cli_print_ratectl(void)
{
    ratectl_stats_t r;
    venc_get_ratectl(&r);
    if (r.target_kbps == 0u) {
        fmt_printf("  Rate control    : constant QP %u (target 0)\n", (unsigned)r.cqp);
    } else {
        fmt_printf("  Rate control    : constant bit rate, target %u kb/s, buffer %u ms (%u bits), QP range %u..%u\n",
                   (unsigned)r.target_kbps, (unsigned)r.buffer_ms, (unsigned)(r.target_kbps * r.buffer_ms), (unsigned)r.qp_min,
                   (unsigned)r.qp_max);
    }
    fmt_printf("  Measured rate   : %u kb/s over the last 1 s, %u kb/s over the last 10 s (coded picture bits, %u s recorded)\n",
               (unsigned)(r.bits_1s / 1000u), (unsigned)(r.bits_10s / 1000u), (unsigned)r.seconds);
    if (r.target_kbps == 0u) {
        fmt_printf("  Buffer fill     : not used in constant QP mode\n");
    } else {
        fmt_printf("  Buffer fill     : ");
        cli_print_permille(r.fill_permille);
        fmt_printf(" (min ");
        cli_print_permille(r.fill_lo_permille);
        fmt_printf(", max ");
        cli_print_permille(r.fill_hi_permille);
        fmt_printf(" since clear)\n");
    }
    fmt_printf("  Picture QP      : last %u; since clear min %u, avg %u.%02u, max %u (%u pictures)\n", (unsigned)r.qp_last,
               (unsigned)r.qp_lo, (unsigned)(r.qp_avg_x100 / 100u), (unsigned)(r.qp_avg_x100 % 100u), (unsigned)r.qp_hi,
               (unsigned)r.pictures);
    fmt_printf("  Buffer events   : overflow %u (%u below QP max), underflow %u\n", (unsigned)r.overflow,
               (unsigned)r.overflow_below_max, (unsigned)r.underflow);
    {
        rtlnet_csi2_rx_state_t cst;
        board_probe_t pp;
        if (board_probe(g_core_csi2.base, g_core_csi2.id, &pp) && rtlnet_csi2_rx_read_state(RTLNET_PLAT_CSI2_BASE, &cst) == 0) {
            cli_print_pattern(&cst);
        }
    }
}

/**
 * @brief SHOW ENCODER HISTORY {COUNT}: the per-second record (bits, mean QP, buffer fill), oldest first.
 * @param ctx argv[0] = number of seconds to list (default 20, at most the 3600 kept).
 * @return 0, or -1 for a bad count.
 */
int cli_show_encoder_history(const MenuCommandContext *ctx)
{
    ratectl_stats_t r;
    uint32_t n = 20u;
    if (ctx->argc > 0 && (cli_parse_u32(ctx->argv[0], &n) != 0 || n < 1u || n > RATECTL_HISTORY_SECONDS)) {
        return cli_bad_value("number of seconds (1..3600)", ctx->argv[0]);
    }
    venc_get_ratectl(&r);
    if (n > r.seconds) {
        n = r.seconds;
    }
    fmt_printf("Encoder history: %u of %u recorded seconds (stream time), oldest first; bits per second = bit rate\n", (unsigned)n,
               (unsigned)r.seconds);
    fmt_printf("  Age (s)       Bits/s  QP avg  Fill %%  Pictures\n");
    for (uint32_t i = n; i-- > 0u;) {
        ratectl_sec_t s;
        if (venc_history(i, &s) != 0) {
            continue;
        }
        fmt_printf("  %7u  %11u  %2u.%02u  %6u  %8u\n", (unsigned)(i + 1u), (unsigned)s.bits, (unsigned)(s.qp_q4 / 16u),
                   (unsigned)((s.qp_q4 % 16u) * 100u / 16u), (unsigned)s.fill_pct, (unsigned)s.pics);
    }
    return 0;
}

/**
 * @brief SHOW STREAM: stream state, counts, bit rate, dropped pictures, TS packets and the mux CPU load.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_stream(const MenuCommandContext *ctx)
{
    venc_status_t s;
    uint32_t sent;
    uint32_t dropped;
    uint32_t retries;
    (void)ctx;
    venc_get_status(&s);
    video_udp_counters(&sent, &dropped, &retries);
    fmt_printf("H.264 stream\n");
    if (s.running) {
        fmt_printf("  State           : running to %u.%u.%u.%u:%u\n", (unsigned)(s.dst_ip >> 24),
                   (unsigned)((s.dst_ip >> 16) & 0xFFu), (unsigned)((s.dst_ip >> 8) & 0xFFu), (unsigned)(s.dst_ip & 0xFFu),
                   (unsigned)s.dst_port);
    } else {
        fmt_printf("  State           : stopped\n");
    }
    fmt_printf("  Video           : %ux%u (mode %s), QP %u (written %u)\n", (unsigned)s.width, (unsigned)s.height,
               s.mode == RTLNET_H264_CTL_MODE_1080P30 ? "1080p30" : "720p30", (unsigned)s.qp, (unsigned)s.qp_used);
    fmt_printf("  Pictures        : %u sent, %u dropped (frame numbers skipped), last frame %u, last %u bytes\n",
               (unsigned)s.pictures, (unsigned)s.dropped_pictures, (unsigned)s.last_frame, (unsigned)s.last_picture_bytes);
    fmt_printf("  GOP             : %u (IDR every %u pictures); %u IDR pictures (%u bytes each on average), %u P pictures (%u bytes each), last %s\n",
               (unsigned)s.gop, (unsigned)s.gop, (unsigned)s.idr_pictures,
               (unsigned)(s.idr_pictures ? s.idr_bytes / s.idr_pictures : 0u), (unsigned)s.p_pictures,
               (unsigned)(s.p_pictures ? s.p_bytes / s.p_pictures : 0u), s.last_idr ? "IDR" : "P");
    fmt_printf("  Bytes           : %u ES, %u TS, bit rate %u kb/s\n", (unsigned)s.es_bytes, (unsigned)s.ts_bytes,
               (unsigned)(s.bit_rate_bps / 1000u));
    cli_print_ratectl();
    fmt_printf("  TS packets      : %u in %u datagrams, %u refused by UDP (UDP sent %u, dropped %u, retries %u)\n",
               (unsigned)s.ts_packets, (unsigned)s.datagrams, (unsigned)s.sink_errors, (unsigned)sent, (unsigned)dropped,
               (unsigned)retries);
    fmt_printf("  CPU load        : TS mux %u.%u %%, encoder handling and mux %u.%u %% (last second); mux time last %u us, max %u us\n",
               (unsigned)(s.mux_load_permille / 10u), (unsigned)(s.mux_load_permille % 10u),
               (unsigned)(s.venc_load_permille / 10u), (unsigned)(s.venc_load_permille % 10u), (unsigned)s.last_mux_us,
               (unsigned)s.max_mux_us);
    fmt_printf("  Cycle time      : %u pictures started; begin to begin min %u, avg %u, max %u us; lag at begin avg %u, max %u us\n",
               (unsigned)s.cyc_n, (unsigned)s.cyc_min_us, (unsigned)s.cyc_avg_us, (unsigned)s.cyc_max_us, (unsigned)s.lag_avg_us,
               (unsigned)s.lag_max_us);
    fmt_printf("  Mux split       : per picture (%u sent) ring read and TS build %u us, pbuf copy %u us, udp_sendto %u us\n",
               (unsigned)s.mux_n, (unsigned)s.mux_ring_ts_us, (unsigned)s.mux_copy_us, (unsigned)s.mux_send_us);
    fmt_printf("  Mux backlog     : %u queued now, max %u (limit %u); %u frames skipped for the backlog\n", (unsigned)s.backlog,
               (unsigned)s.backlog_max, (unsigned)s.backlog_limit, (unsigned)s.skipped_backlog);
    cli_print_notify(&s);
    {
        plat_console_tx_t tx;
        plat_console_tx_stats(&tx);
        fmt_printf("  Console TX      : %s, ring %u bytes, high water %u, %u interrupts, %u refills by the main loop, %u characters lost\n",
                   tx.irq_mode ? "interrupt driven" : "polled", (unsigned)tx.ring_bytes, (unsigned)tx.high_water,
                   (unsigned)tx.irqs, (unsigned)tx.refills, (unsigned)tx.drops);
    }
    fmt_printf("  Errors          : %u; frame buffer published %u, dropped %u\n", (unsigned)s.errors,
               (unsigned)s.fb_published, (unsigned)s.fb_dropped);
    return 0;
}

/**
 * @brief SHOW ENCODER: identity, mode, QP, status and the per-engine statistics registers.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_encoder(const MenuCommandContext *ctx)
{
    rtlnet_h264_ctl_debug_t d;
    venc_status_t s;
    (void)ctx;
    if (!cli_core_check(&g_core_h264)) {
        return 0;
    }
    if (rtlnet_h264_ctl_debug(&d) != 0) {
        fmt_printf("%% the encoder answers with an unexpected VERSION\n");
        return 0;
    }
    venc_get_status(&s);
    fmt_printf("H.264 encoder\n");
    cli_print_core_line(&g_core_h264, d.version);
    fmt_printf("  Build           : %u engines, up to %u x %u macroblocks, interrupt registers %s\n", (unsigned)d.engines,
               (unsigned)d.max_mb_w, (unsigned)d.max_mb_h, d.irq_capable ? "present" : "absent (polled mode only)");
    fmt_printf("  QP              : %u configured, %u written; STATUS 0x%08X (busy %u, done %u, error %u, ring stall %u), ERR_CODE %u\n",
               (unsigned)s.qp, (unsigned)s.qp_used,
               (unsigned)(d.busy | (d.done << 1) | (d.err << 2) | (d.ring_stall << 3)), (unsigned)d.busy, (unsigned)d.done, (unsigned)d.err,
               (unsigned)d.ring_stall, (unsigned)d.err_code);
    fmt_printf("  GOP             : %u (IDR every %u pictures, P pictures between), last picture %s\n", (unsigned)s.gop,
               (unsigned)s.gop, s.last_idr ? "IDR" : "P");
    cli_print_notify(&s);
    if (d.irq_capable) {
        fmt_printf("  Interrupt regs  : IRQ_STATUS 0x%02X, IRQ_ENABLE 0x%02X, global enable %u; last error code %u\n", (unsigned)d.irq_status,
                   (unsigned)d.irq_enable, (unsigned)d.irq_global, (unsigned)s.last_err_code);
    }
    cli_print_ratectl();
    cli_print_high_profile(s.hp_forced_idr);
    cli_print_transform8x8();
    fmt_printf("  Pictures        : %u coded (PIC_COUNT), %u slices\n", (unsigned)d.pic_count, (unsigned)d.slice_count);
    for (uint32_t e = 0; e < d.engines; e++) {
        const rtlnet_h264_ctl_stats_t *t = &d.eng[e];
        fmt_printf("  Engine %u        : %u macroblocks, picture %u cycles (%u per macroblock), last interval %u, max %u;"
                   " busy cycles read %u coder %u write %u\n",
                   (unsigned)e, (unsigned)t->mb_count, (unsigned)t->pic_cyc, (unsigned)(t->mb_count ? t->pic_cyc / t->mb_count : 0u),
                   (unsigned)t->cyc_last, (unsigned)t->cyc_max, (unsigned)t->rd_cyc, (unsigned)t->pk_cyc, (unsigned)t->wr_cyc);
    }
    return 0;
}
